"use client"

import { useState } from "react"
import { MainLayout } from "@/components/main-layout"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Badge } from "@/components/ui/badge"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { Plus, Search, FileText, Download, Send, Eye, Trash, Edit } from "lucide-react"
import { useDataStore } from "@/lib/data-store"
import { formatUSD } from "@/lib/money"

// Quotes are sourced from the central data store (`useDataStore`) at runtime.

const statusColors = {
  draft: "secondary",
  sent: "default",
  accepted: "default",
  rejected: "destructive",
} as const

function QuoteFormContent({
  initialData,
  onSubmit,
  submitLabel,
}: {
  initialData?: any
  onSubmit: (p: any) => Promise<void>
  submitLabel?: string
}) {
  const [client, setClient] = useState(initialData?.client || "")
  const [project, setProject] = useState(initialData?.project || "")
  const [validUntil, setValidUntil] = useState(initialData?.validUntil || "")
  const [amount, setAmount] = useState(initialData?.amount ? String(initialData.amount) : "")
  const [status, setStatus] = useState(initialData?.status || "draft")

  return (
    <div>
      <div className="grid gap-4 py-4">
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label>Client</Label>
            <Input value={client} onChange={(e) => setClient(e.target.value)} />
          </div>
          <div className="space-y-2">
            <Label>Project Name</Label>
            <Input value={project} onChange={(e) => setProject(e.target.value)} />
          </div>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label>Valid Until</Label>
            <Input type="date" value={validUntil} onChange={(e) => setValidUntil(e.target.value)} />
          </div>
          <div className="space-y-2">
            <Label>Amount</Label>
            <Input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} />
          </div>
        </div>
        <div className="space-y-2">
          <Label>Status</Label>
          <Select value={status} onValueChange={(v) => setStatus(v)}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="draft">Draft</SelectItem>
              <SelectItem value="sent">Sent</SelectItem>
              <SelectItem value="accepted">Accepted</SelectItem>
              <SelectItem value="rejected">Rejected</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>
      <div className="flex justify-end gap-3">
        <Button
          variant="outline"
          onClick={() => {
            setClient("")
            setProject("")
            setValidUntil("")
            setAmount("")
            setStatus("draft")
          }}
        >
          Clear
        </Button>
        <Button
          onClick={async () => {
            const payload = { client, project, date: initialData?.date || new Date().toISOString().slice(0, 10), validUntil, amount: Number(amount || 0), status }
            await onSubmit(payload)
          }}
        >
          {submitLabel || (initialData ? "Save Changes" : "Create Quote")}
        </Button>
      </div>
    </div>
  )
}

export default function QuotesPage() {
  const [searchQuery, setSearchQuery] = useState("")
  const [statusFilter, setStatusFilter] = useState("all")
  const [selectedQuote, setSelectedQuote] = useState<any | null>(null)
  const store = useDataStore()
  const quotes = useDataStore((s) => s.quotes || [])
  const [editingQuote, setEditingQuote] = useState<any | null>(null)
  const [editingOpen, setEditingOpen] = useState(false)

  async function deleteQuote(id: string) {
    if (!confirm("Are you sure you want to delete this quote?")) return
    if (selectedQuote?.id === id) setSelectedQuote(null)
    const ok = await store.deleteQuote(id)
    if (!ok) alert('Failed to delete quote on server')
  }

  const filteredQuotes = quotes.filter((quote: any) => {
    const matchesSearch =
      quote.id.toLowerCase().includes(searchQuery.toLowerCase()) ||
      quote.client.toLowerCase().includes(searchQuery.toLowerCase()) ||
      quote.project.toLowerCase().includes(searchQuery.toLowerCase())
    const matchesStatus = statusFilter === "all" || quote.status === statusFilter
    return matchesSearch && matchesStatus
  })

  return (
    <MainLayout>
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold tracking-tight">Quotes</h1>
            <p className="text-muted-foreground">Create and manage project quotes</p>
          </div>
          <Dialog>
            <DialogTrigger asChild>
              <Button variant="brand">
                <Plus className="mr-2 h-4 w-4" />
                New Quote
              </Button>
            </DialogTrigger>
            <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
              <DialogHeader>
                <DialogTitle>Create New Quote</DialogTitle>
                <DialogDescription>Generate a quote for a client project</DialogDescription>
              </DialogHeader>
                <QuoteFormContent onSubmit={async (payload) => {
                  // optimistic UI add via store
                  const ok = await store.createQuote(payload)
                  if (!ok) alert('Failed to create quote on server')
                }} />
            </DialogContent>
          </Dialog>
        </div>

        <Card>
          <CardHeader>
            <div className="flex items-center gap-4">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                <Input
                  placeholder="Search quotes..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pl-9"
                />
              </div>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger className="w-[180px]">
                  <SelectValue placeholder="All Status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="draft">Draft</SelectItem>
                  <SelectItem value="sent">Sent</SelectItem>
                  <SelectItem value="accepted">Accepted</SelectItem>
                  <SelectItem value="rejected">Rejected</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {filteredQuotes.map((quote) => (
                <Card
                  key={quote.id}
                  className="cursor-pointer hover:shadow-md transition-shadow"
                  onClick={() => setSelectedQuote(quote)}
                >
                  <CardContent className="p-6">
                    <div className="flex items-center justify-between">
                      <div className="flex items-start gap-4">
                        <div className="flex h-12 w-12 items-center justify-center rounded-lg bg-primary/10">
                          <FileText className="h-6 w-6 text-primary" />
                        </div>
                        <div className="space-y-1">
                          <div className="flex items-center gap-2">
                            <h3 className="font-semibold">{quote.id}</h3>
                            <Badge variant={statusColors[quote.status as keyof typeof statusColors]}>
                              {String(quote.status || '').charAt(0).toUpperCase() + String(quote.status || '').slice(1)}
                            </Badge>
                          </div>
                          <p className="text-sm font-medium">{quote.client}</p>
                          <p className="text-sm text-muted-foreground">{quote.project}</p>
                          <div className="flex items-center gap-4 text-xs text-muted-foreground">
                            <span>Created: {quote.date}</span>
                            <span>Valid until: {quote.validUntil}</span>
                            <span>{(quote.items || []).length} items</span>
                          </div>
                        </div>
                      </div>
                      <div className="flex items-center gap-6">
                          <div className="text-right">
                            <p className="text-sm text-muted-foreground">Total Amount</p>
                            <p className="text-3xl font-bold">{formatUSD((quote.amount || 0))}</p>
                          </div>
                          <div className="flex gap-2">
                            <Button
                              size="icon"
                              variant="ghost"
                              onClick={(e) => {
                                e.stopPropagation()
                                setSelectedQuote(quote)
                              }}
                            >
                              <Eye className="h-4 w-4" />
                            </Button>
                            <Button
                              size="icon"
                              variant="ghost"
                              onClick={(e) => {
                                  e.stopPropagation()
                                  setEditingQuote(quote)
                                  setEditingOpen(true)
                                }}
                            >
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button
                              size="icon"
                              variant="ghost"
                              onClick={(e) => {
                                e.stopPropagation()
                                // placeholder for download
                              }}
                            >
                              <Download className="h-4 w-4" />
                            </Button>
                            <Button
                              size="icon"
                              variant="ghost"
                              onClick={(e) => {
                                e.stopPropagation()
                                // placeholder for send
                              }}
                            >
                              <Send className="h-4 w-4" />
                            </Button>
                            <Button
                              size="icon"
                              variant="destructive"
                              onClick={(e) => {
                                e.stopPropagation()
                                deleteQuote(quote.id)
                              }}
                            >
                              <Trash className="h-4 w-4" />
                            </Button>
                          </div>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          </CardContent>
        </Card>

        <div className="grid gap-4 md:grid-cols-4">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium">Total Quotes</CardTitle>
            </CardHeader>
            <CardContent>
                <div className="text-2xl font-bold">{quotes.length}</div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium">Total Value</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{formatUSD(quotes.reduce((sum: number, q: any) => sum + (q.amount || 0), 0))}</div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium">Accepted</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{quotes.filter((q: any) => q.status === "accepted").length}</div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-sm font-medium">Pending</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{quotes.filter((q: any) => q.status === "sent").length}</div>
            </CardContent>
          </Card>
        </div>

        <Dialog open={editingOpen} onOpenChange={(open) => { setEditingOpen(open); if (!open) setEditingQuote(null) }}>
          <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>Edit Quote - {editingQuote?.id}</DialogTitle>
              <DialogDescription>
                Edit the details for the selected quote
              </DialogDescription>
            </DialogHeader>
                {editingQuote && (
              <QuoteFormContent
                initialData={editingQuote}
                submitLabel="Save Changes"
                onSubmit={async (payload) => {
                  const id = editingQuote?.id
                  if (!id) return
                      const ok = await store.updateQuote(id, payload)
                      if (ok) {
                        setEditingOpen(false)
                        setEditingQuote(null)
                      } else {
                        alert('Failed to update quote on server')
                      }
                }}
              />
            )}
          </DialogContent>
        </Dialog>

        <Dialog open={!!selectedQuote} onOpenChange={() => setSelectedQuote(null)}>
          <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
            <DialogHeader>
              <DialogTitle>Quote Details - {selectedQuote?.id}</DialogTitle>
              <DialogDescription>
                {selectedQuote?.client} - {selectedQuote?.project}
              </DialogDescription>
            </DialogHeader>
            {selectedQuote && (
              <div className="space-y-6">
                <div className="grid grid-cols-2 gap-4 text-sm">
                  <div>
                    <p className="text-muted-foreground">Date Created</p>
                    <p className="font-medium">{selectedQuote.date}</p>
                  </div>
                  <div>
                    <p className="text-muted-foreground">Valid Until</p>
                    <p className="font-medium">{selectedQuote.validUntil}</p>
                  </div>
                </div>
                <div>
                  <h3 className="font-semibold mb-3">Quote Items</h3>
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Item</TableHead>
                        <TableHead className="text-right">Quantity</TableHead>
                        <TableHead className="text-right">Price</TableHead>
                        <TableHead className="text-right">Total</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {(selectedQuote.items || []).map((item, i) => (
                        <TableRow key={i}>
                          <TableCell>{item.name}</TableCell>
                          <TableCell className="text-right">{item.quantity}</TableCell> 
                          <TableCell className="text-right">{formatUSD(item.price)}</TableCell>
                          <TableCell className="text-right">{formatUSD((item.quantity * item.price))}</TableCell>
                        </TableRow>
                      ))}
                      <TableRow>
                        <TableCell colSpan={3} className="text-right font-semibold">
                          Total
                        </TableCell>
                        <TableCell className="text-right font-bold text-lg">
                          {formatUSD(selectedQuote.amount)}
                        </TableCell>
                      </TableRow>
                    </TableBody>
                  </Table>
                </div>
                <div className="flex justify-end gap-3">
                  <Button variant="outline">
                    <Download className="mr-2 h-4 w-4" />
                    Download PDF
                  </Button>
                  <Button>
                    <Send className="mr-2 h-4 w-4" />
                    Send to Client
                  </Button>
                </div>
              </div>
            )}
          </DialogContent>
        </Dialog>
      </div>
    </MainLayout>
  )
}
